import React, { useState, useEffect } from 'react';
import { useAuth } from './AuthContext';
import { useNavigate } from 'react-router-dom';
import './Profile.css';

function Profile() {
    const { isAuthenticated, logout, currentUser } = useAuth();
    const [username, setUsername] = useState('');
    const [newUsername, setNewUsername] = useState('');
    const [newPassword, setNewPassword] = useState('');
    const [error, setError] = useState('');
    const [successMessage, setSuccessMessage] = useState('');
    const navigate = useNavigate();

    // Felhasználó adatainak betöltése
    useEffect(() => {
        if (!isAuthenticated || !currentUser) {
            navigate('/login');
            return;
        }

        const fetchUserData = async () => {
            try {
                const token = localStorage.getItem('token');
                const response = await fetch('http://localhost:5123/User/me', {
                    method: 'GET',
                    headers: {
                        'Authorization': `Bearer ${token}`, // JWT token használata
                    },
                });

                if (!response.ok) {
                    throw new Error('Hiba a felhasználói adatok lekérésekor');
                }

                const data = await response.json();
                setUsername(data.username); // Felhasználónév beállítása
            } catch (error) {
                setError('Hiba történt a felhasználói adatok betöltésekor');
            }
        };

        fetchUserData();
    }, [isAuthenticated, currentUser, navigate]);

    // Felhasználónév és jelszó módosítása
    const handleUpdateProfile = async (e) => {
        e.preventDefault();

        try {
            const token = localStorage.getItem('token');
            const response = await fetch(`http://localhost:5123/User/${username}`, {
                method: 'PUT',
                headers: {
                    'Content-Type': 'application/json',
                    'Authorization': `Bearer ${token}`, // JWT token használata
                },
                body: JSON.stringify({
                    username: newUsername || username, // Ha nincs új felhasználónév, marad a régi
                    password: newPassword,
                }),
            });

            if (!response.ok) {
                throw new Error('Hiba történt a profil frissítésekor');
            }

            setSuccessMessage('Profil sikeresen frissítve!');
            setError('');
            setUsername(newUsername || username); // Frissítjük a felhasználónevet
            setNewUsername('');
            setNewPassword('');
        } catch (error) {
            setError('Hiba történt a profil frissítésekor');
            setSuccessMessage('');
        }
    };

    return (
        <div className="profile-container">
            <h2>Profil</h2>
            {error && <div className="error-message">{error}</div>}
            {successMessage && <div className="success-message">{successMessage}</div>}
            <form onSubmit={handleUpdateProfile}>
                <div className="form-group">
                    <label htmlFor="username">Felhasználónév</label>
                    <input
                        type="text"
                        className="form-control"
                        id="username"
                        value={newUsername}
                        onChange={(e) => setNewUsername(e.target.value)}
                        placeholder={username || 'Új felhasználónév'}
                    />
                </div>
                <div className="form-group">
                    <label htmlFor="password">Új jelszó</label>
                    <input
                        type="password"
                        className="form-control"
                        id="password"
                        value={newPassword}
                        onChange={(e) => setNewPassword(e.target.value)}
                        placeholder="Új jelszó"
                    />
                </div>
                <button type="submit" className="btn btn-primary">
                    Módosítás
                </button>
            </form>
            <button className="btn btn-danger mt-3" onClick={logout}>
                Kijelentkezés
            </button>
        </div>
    );
}

export default Profile;
